script:
export const meta = {
  name: 'review_loop',
  description: 'Actor-Critic review→fix→re-review loop: adversarial verification, severity gating, scope-locking, per-round diff refresh, bounded convergence',
  phases: [{ title: 'Scope' }, { title: 'Converge' }, { title: 'Report' }],
}

// ---- Config (overridable via args; CLI key=value arrive as strings) ----
const num = (v, d) => { const n = Number(v); return Number.isFinite(n) ? n : d }
const consecutiveEmpty = 2 // dry rounds loopUntilDry must observe before it may certify convergence
const scope         = (args && args.scope) || (args && args._) || 'the current branch vs its merge-base with main, else staged, else HEAD'
const maxRounds     = num(args && args.maxRounds, 5)
const reviewers     = num(args && args.reviewers, 2)
const threshold     = num(args && args.threshold, 1.0)
const maxChunkLines = num(args && args.maxChunkLines, 500)
let gateSeverities = (args && args.severityGate) || ['blocker', 'high']
if (typeof gateSeverities === 'string') gateSeverities = gateSeverities.split(',').map((s) => s.trim()).filter(Boolean)

const findingSchema = {
  type: 'object',
  properties: { findings: { type: 'array', items: {
    type: 'object',
    properties: {
      id: { type: 'string' }, severity: { type: 'string', enum: ['blocker', 'high', 'medium', 'suggestion'] },
      category: { type: 'string', enum: ['security', 'correctness', 'performance', 'maintainability'] },
      location: { type: 'string' }, description: { type: 'string' }, evidence: { type: 'string' },
      repro_test: { type: 'string' }, boundary_owner: { type: 'string', enum: ['current', 'server', 'external'] },
      confidence: { type: 'string', enum: ['low', 'medium', 'high'] },
    },
    required: ['id', 'severity', 'category', 'location', 'description', 'boundary_owner'],
    // Enforce the repro discipline where it matters: blocker/high must carry a repro_test.
    if: { properties: { severity: { enum: ['blocker', 'high'] } } },
    then: { required: ['id', 'severity', 'category', 'location', 'description', 'boundary_owner', 'repro_test'] },
  } } },
  required: ['findings'],
}

// Stable identity + de-duplication. Two keys on purpose:
//  - keyOf (category+location) is the TIGHT loop-identity key: critic ids are
//    non-deterministic across rounds, so loopUntilDry keys on it to detect
//    no-progress / oscillation (duplicate-only rounds are dry).
//  - reportKeyOf adds a description fingerprint so the REPORT dedup does not
//    silently merge two genuinely different issues at the same location.
const keyOf = (f) => (f.category || '?') + '|' + (f.location || '?')
const fp = (s) => { let h = 0; const str = String(s || ''); for (let i = 0; i < str.length; i++) { h = (h * 31 + str.charCodeAt(i)) | 0 } return h }
const reportKeyOf = (f) => keyOf(f) + '|' + fp(f.description)
const dedupBy = (arr, keyFn) => {
  const seen = {}
  const out = []
  for (const f of arr) { const k = keyFn(f); if (!seen[k]) { seen[k] = true; out.push(f) } }
  return out
}

const laneNames = ['maintainability', 'correctness', 'security']
const laneCount = laneNames.length

const RULES_HEAD =
  '\n\nRULES: Comment ONLY on the diff below plus at most one hop of direct dependencies. Flag issues; do NOT rewrite code. ' +
  'Severity blocker/high = crashes, security, logic bugs, measurable perf/arch regressions; medium/suggestion = style, micro-opts, speculative edge cases. ' +
  'Set boundary_owner=current only if the fix belongs in THIS diff. For every blocker/high include a concrete repro_test that fails on current behavior. Quote evidence.\n\nDIFF:\n'
const buildRules = (d) => RULES_HEAD + d

// ---- Phase 1: resolve scope, capture diff, size-gate ----
phase('Scope')
const scan = await agent(
  'Resolve review scope: ' + scope + '. Run git to capture the unified diff and changed files. ' +
  'Compute the total added+removed line count DETERMINISTICALLY, e.g. `git diff --numstat <range> | awk \'{a+=$1; d+=$2} END {print a+d}\'` — do not eyeball it. ' +
  'Return the diff, the changed-file list, and that line count.',
  { tier: 'small', label: 'scope + diff', schema: { type: 'object', properties: {
      diff: { type: 'string' }, files: { type: 'array', items: { type: 'string' } }, lineCount: { type: 'number' }
    }, required: ['diff', 'files', 'lineCount'] } })
if (!scan || typeof scan.diff !== 'string') {
  return { verdict: 'ABORTED — could not resolve scope/diff', roundsRun: 0, totalAddressed: 0, totalResolved: 0,
           unresolved: [], unverified: [], tracked: [], trajectory: [], report: 'Scope agent returned no usable diff.' }
}
let currentDiff = scan.diff
const oversized = scan.lineCount > maxChunkLines
if (oversized) log('PR is ' + scan.lineCount + ' lines (> ' + maxChunkLines + '); large diffs converge poorly — skipping the loop and flagging NEEDS SPLIT.')

// ---- Phase 2: bounded Actor-Critic convergence loop ----
phase('Converge')
let lastSurvivors = []
let roundsRun = 0
const tracked = []
const unverified = []
// SEC-R3-002: findings with split verifier votes (some real, some not) are
// DISPUTED, not clean and not silently dropped — they escalate to a human.
const disputed = []
const fixLog = []
const trajectory = []
let found = []
// MAINT-R3-001: track whether the loop ACTUALLY observed consecutiveEmpty
// consecutive dry rounds. Lane coverage and convergence termination are
// different facts: hitting maxRounds after a single dry round is NOT clean.
let convergedDry = 0
// MAINT-R4-001: convergence evidence must track CLEAN post-fix critic rounds, not
// loopUntilDry's dedup state. A duplicate survivor (previously-seen keyOf) still runs
// the fixer this round, so it is NOT dry — keying off "no new key" would let one empty
// review after the final fix combine with a still-failing round to falsely certify
// CONVERGED CLEAN. Increment only when THIS round produced zero survivors.
const recordRound = (arr) => {
  if ((arr || []).length) convergedDry = 0; else convergedDry++
  return arr
}

if (!oversized) {
  found = await loopUntilDry({
    maxRounds, consecutiveEmpty, key: keyOf,
    round: async (r) => {
      roundsRun = r + 1

      // P0: refresh the diff each round so critics review the CURRENT (post-fix)
      // state instead of a frozen round-0 snapshot. Without this the loop keeps
      // re-flagging already-fixed issues and can never observe convergence.
      if (r > 0) {
        const rescan = await agent(
          'Re-capture the CURRENT unified diff for review scope: ' + scope +
          ' (it now reflects fixes applied in prior rounds). Compute the total added+removed line count DETERMINISTICALLY via `git diff --numstat ... | awk`. Return the diff and that line count.',
          { tier: 'small', label: 'rescan r' + roundsRun, schema: { type: 'object', properties: {
              diff: { type: 'string' }, lineCount: { type: 'number' } }, required: ['diff'] } })
        if (rescan && typeof rescan.diff === 'string') currentDiff = rescan.diff
        else log('Rescan in round ' + roundsRun + ' returned null; reusing prior diff snapshot (may be stale).')
      }
      const rules = buildRules(currentDiff)

      // CRITIC: independent isolated lanes (separate sessions => no self-agreeableness).
      // All three critics run on criticBig (a DIFFERENT model family than the fixerBig
      // fixer) to decorrelate blind spots on the re-review of each fix.
      const lanes = await parallel([
        () => agent('Read the skill file at ~/.agents/skills/thermo-nuclear-code-quality-review/SKILL.md (expand ~ to your home dir) and apply it as a maintainability critic.' + rules,
                    { tier: 'criticBig', label: 'maintainability r' + roundsRun, schema: findingSchema }),
        () => agent('Correctness critic: trace the most critical path end-to-end; logic bugs, missing authz, boundary/edge errors.' + rules,
                    { tier: 'criticBig', label: 'correctness r' + roundsRun, schema: findingSchema }),
        () => agent('Security critic: injection, secrets, authz, unsafe handling of untrusted input.' + rules,
                    { tier: 'criticBig', label: 'security r' + roundsRun, schema: findingSchema }),
      ])
      // Record missing coverage (a failed lens is not "clean").
      const lanesOk = lanes.filter(Boolean).length
      lanes.forEach((l, i) => { if (!l) log('Critic lane "' + laneNames[i] + '" returned null (missing coverage) in round ' + roundsRun + '.') })
      const all = lanes.filter(Boolean).flatMap((l) => (l && l.findings) || [])

      // CLASSIFY: loop-drivers vs tracked-for-later
      const gated = []
      for (const f of all) {
        if (gateSeverities.indexOf(f.severity) >= 0 && f.boundary_owner === 'current') gated.push(f)
        else tracked.push(f)
      }
      if (!gated.length) {
        trajectory.push({ round: roundsRun, lanesOk, findings: all.length, gated: 0, survivors: 0, unverified: 0, fixed: 0, applied: null, testsPass: null })
        lastSurvivors = []
        return recordRound([])
      }

      // VERIFY: adversarial skeptics must REFUTE; only survivors proceed.
      // threshold defaults to 1.0 (unanimous) so a single non-refutation is not
      // enough to keep a finding — precision over recall to fight false positives.
      const checks = await parallel(gated.map((f) => () =>
        verify('Category ' + f.category + ' at ' + f.location + ': ' + f.description +
               '\nClaimed repro: ' + (f.repro_test || '(none)') +
               '\nREAL only if the repro would truly fail on current behavior and the fix belongs in this diff.',
               { reviewers, threshold, lens: [f.category, 'is this edge case already implicitly handled?'] })))
      // A NULL verify is missing coverage, NOT a refutation — escalate rather than
      // silently drop a potentially-real blocker.
      const survivors = []
      let unverifiedThisRound = 0
      gated.forEach((f, i) => {
        const c = checks[i]
        // A NULL verify is missing coverage; so is a PARTIAL verify. `verify` computes its ratio over SUCCESSFUL votes only (it drops failed reviewers), so if any requested reviewer failed (c.total < reviewers) even a 1.0 threshold is not truly unanimous across the configured reviewers. Escalate both rather than routing a half-covered finding to the fixer.
        const covered = c && typeof c.total === 'number' ? c.total : 0
        if (!c || covered < reviewers) { unverified.push(f); unverifiedThisRound++; log('Verification incomplete for ' + keyOf(f) + ' in round ' + roundsRun + ' (covered ' + covered + '/' + reviewers + '); routing to human escalation (not silently dropped).') }
        else if (c.real) survivors.push(f)
        // Covered by all reviewers but not unanimous: some voted real, some did not.
        // Under a >0.5 threshold this fails c.real yet is NOT a clean refutation, so
        // escalate as disputed instead of dropping a possibly-valid blocker. Only a
        // unanimous 'not real' (realCount === 0) is a genuine refutation we discard.
        else if ((c.realCount || 0) > 0) { disputed.push(f); log('Finding ' + keyOf(f) + ' DISPUTED in round ' + roundsRun + ' (' + c.realCount + '/' + c.total + ' reviewers voted real); escalating (not dropped).') }
      })
      lastSurvivors = survivors
      if (!survivors.length) {
        trajectory.push({ round: roundsRun, lanesOk, findings: all.length, gated: gated.length, survivors: 0, unverified: unverifiedThisRound, fixed: 0, applied: null, testsPass: null })
        return recordRound([])
      }

      // ACTOR: single fixer holds fix authority; fixes survivors ONLY, adds
      // failing->passing tests, stays in scope. Runs on fixerBig (distinct family).
      const fix = await agent(
        'You are the fixer. Apply MINIMAL fixes for ONLY these verified blockers, add a test that fails before / passes after each, ' +
        'stay within the diff scope, then report what changed.\n\n' + JSON.stringify(survivors),
        { tier: 'fixerBig', label: 'fix r' + roundsRun })

      // VALIDATE: independently confirm the fixes actually landed and tests pass,
      // so the reported metric is resolution ("did it get fixed?"), not merely
      // "handed to the fixer". A null validation is missing coverage, not success.
      const validation = await agent(
        'You are the validator. The fixer just applied fixes for these findings:\n' + JSON.stringify(survivors) +
        '\n\nFixer report:\n' + String(fix) +
        '\n\nIndependently confirm via git/tooling that the intended changes are present in the working tree, then run the project test/build command. ' +
        'Return applied (were the intended changes made) and testsPass (did the suite/build pass).',
        { tier: 'medium', label: 'validate r' + roundsRun, schema: { type: 'object', properties: {
            applied: { type: 'boolean' }, testsPass: { type: 'boolean' }, notes: { type: 'string' } }, required: ['applied', 'testsPass'] } })
      if (!validation) log('Validation returned null in round ' + roundsRun + '; fix landing/tests UNCONFIRMED.')
      const applied = validation ? validation.applied : null
      const testsPass = validation ? validation.testsPass : null

      trajectory.push({ round: roundsRun, lanesOk, findings: all.length, gated: gated.length, survivors: survivors.length, unverified: unverifiedThisRound, fixed: survivors.length, applied, testsPass })
      fixLog.push({ round: roundsRun, fixed: survivors.length, applied, testsPass, findings: survivors, summary: fix, validationNotes: validation && validation.notes })
      return recordRound(survivors)
    },
  })
}

// ---- Phase 3: report + verdict + escalation ----
phase('Report')
const trackedUnique = dedupBy(tracked, reportKeyOf)
const unverifiedUnique = dedupBy(unverified, reportKeyOf)
const disputedUnique = dedupBy(disputed, reportKeyOf)
const totalAddressed = found.length
// Resolution counts UNIQUE findings (keyed by keyOf, matching loopUntilDry's dedup) whose fixes were validated as landed + passing — never a per-round sum, which could exceed totalAddressed when the same finding recurs across rounds. A finding still surfacing as a survivor at loop end is NOT resolved even if an earlier round's validation passed (the fix did not hold).
const unresolvedKeys = {}
for (const f of lastSurvivors) unresolvedKeys[keyOf(f)] = true
const resolvedKeys = {}
for (const e of fixLog) {
  if (e.applied === true && e.testsPass === true) {
    for (const f of (e.findings || [])) { const k = keyOf(f); if (!unresolvedKeys[k]) resolvedKeys[k] = true }
  }
}
const totalResolved = Object.keys(resolvedKeys).length

// Coverage-aware clean verdict: a round that returns [] is NOT clean if the
// critic lanes did not fully cover it, and "clean" must also account for
// blockers we could not verify. Inspect the terminal (loop-ending) rounds.
const terminal = trajectory.slice(-2)
const coverageComplete = terminal.length > 0 && terminal.every((t) => t.lanesOk === laneCount)
// A fix whose landing or tests were never confirmed (validator returned null, or reported applied/testsPass !== true) is UNCONFIRMED coverage — missing post-fix evidence, not success. It must not be certified clean just because later critic rounds surfaced no survivors.
const unconfirmedFixes = fixLog.filter((e) => e.applied !== true || e.testsPass !== true)
// MAINT-R3-001: only certify convergence when the loop genuinely reached the
// required consecutive dry rounds; otherwise it stopped at the round cap.
const converged = convergedDry >= consecutiveEmpty

const verdict =
    oversized ? 'NEEDS SPLIT — too large to converge; split then re-run'
  : (lastSurvivors.length > 0 && roundsRun >= maxRounds) ? 'STOPPED AT CAP — escalate to human'
  : (lastSurvivors.length === 0 && !converged) ? ('STOPPED AT CAP — did not reach ' + consecutiveEmpty + ' consecutive dry rounds; do NOT treat as clean, escalate to human')
  : (lastSurvivors.length === 0 && disputedUnique.length > 0) ? ('CONVERGED w/ DISPUTED — ' + disputedUnique.length + ' finding(s) had split verifier votes; escalate to human')
  : (lastSurvivors.length === 0 && !coverageComplete) ? 'INCONCLUSIVE — incomplete critic coverage; do NOT treat as clean, escalate to human'
  : (lastSurvivors.length === 0 && unverifiedUnique.length > 0) ? ('CONVERGED w/ UNVERIFIED — ' + unverifiedUnique.length + ' finding(s) could not be verified; escalate to human')
  : (lastSurvivors.length === 0 && unconfirmedFixes.length > 0) ? ('CONVERGED w/ UNCONFIRMED FIXES — ' + unconfirmedFixes.length + ' fix round(s) had unconfirmed landing/tests; do NOT treat as clean, escalate to human')
  : lastSurvivors.length === 0 ? 'CONVERGED CLEAN'
  : 'STOPPED — no new blockers (possible oscillation on remaining items)'

const report = await agent(
  'Write a concise final report: verdict, per-round trajectory, resolution rate (validated-resolved/total gated), ' +
  'fixes whose landing or tests were NOT confirmed, unresolved blockers to escalate, findings that could NOT be verified (escalate to human), and the tracked-for-later list. ' +
  'Do NOT re-litigate resolved items.\n\n' +
  'VERDICT: ' + verdict + '\nROUNDS: ' + roundsRun +
  '\nADDRESSED (handed to fixer): ' + totalAddressed + '\nRESOLVED (validated landed + tests pass): ' + totalResolved +
  '\nTRAJECTORY:\n' + JSON.stringify(trajectory) +
  '\nFIX LOG:\n' + JSON.stringify(fixLog) +
  '\nUNRESOLVED:\n' + JSON.stringify(lastSurvivors) +
  '\nUNVERIFIED (verification failed — escalate):\n' + JSON.stringify(unverifiedUnique) +
  '\nDISPUTED (split verifier votes — escalate):\n' + JSON.stringify(disputedUnique) +
  '\nTRACKED:\n' + JSON.stringify(trackedUnique),
  { tier: 'medium', label: 'synthesis' })

return { verdict, roundsRun, totalAddressed, totalResolved, unresolved: lastSurvivors, unverified: unverifiedUnique, disputed: disputedUnique, tracked: trackedUnique, trajectory, report }
